const raw = $json.text ?? $json.output ?? '';
const attempt = $runIndex;
let d;
try { d = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch (e) { return { json: { ok: false, attempt, error: 'Your reply was not valid JSON. Reply with ONLY the JSON object.' } }; }
// Guard: every cited tag must exist in the recalled evidence.
const known = new Set($('Recall').first().json.items.map(i => i.tag));
const bad = (d.cited || []).filter(t => !known.has(t));
if (bad.length) return { json: { ok: false, attempt, error: 'You cited tags that are not in the evidence: ' + bad.join(', ') + '. Copy tags exactly as written.' } };
if (d.summary && !(d.cited || []).some(t => t.startsWith('fact:') || t.startsWith('procedure:')))
  return { json: { ok: false, attempt, error: 'A decision must cite at least one fact or procedure.' } };
return { json: { ok: true, attempt, summary: d.summary || null, cited: d.cited || [], reasoning: d.reasoning || '', missing: d.missing || null } };

