const raw = $json.text ?? $json.output ?? '';
let v;
try { v = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch (e) { v = { approved: false, reason: 'Verifier output was not valid JSON; failing closed.' }; }
// Fail closed: approval needs an explicit true AND a reason naming an evidence tag.
const known = new Set($('Recall').first().json.items.map(i => i.tag));
const namesATag = [...known].some(t => (v.reason || '').includes(t));
if (v.approved === true && !namesATag) {
  v.approved = false;
  v.reason = 'Approval rejected by guard: reason did not cite any evidence tag. ' + (v.reason || '');
}
v.approved = v.approved === true;
return { json: v };
